package com.ats.geospatial;

public final class SurveyProjectIntakeParser {
    private static int parsedProjectCount;

    private SurveyProjectIntakeParser() {}

    public static int parseEstimatedRecords(String value) {
        int parsed = Integer.parseInt(value);
        parsedProjectCount++;
        return parsed;
    }

    public static int toWholeCompletionPercent(double value) {
        return (int) value;
    }

    public static String formatEstimatedRecords(int value) {
        return Integer.toString(value);
    }

    public static int getParsedProjectCount() {
        return parsedProjectCount;
    }
}
